traces=[]
for title,path,start,end,required in [
 ('Tokenizer retains the mask with batch-longest padding','crates/intel/esp/src/embed/bert/tokenizer.rs','    pub fn encode_batch(', '\n#[cfg(test)]', ['get_attention_mask()', 'attention_mask,']),
 ('Provider sends IDs without the mask','crates/intel/esp/src/embed/bert/provider.rs','    fn forward_sentence_batch(', '\n#[cfg(feature = "bert-validation")]\nasync fn trace_int_tensor', ['batch.input_ids', 'model.forward_sentence(']),
 ('Self attention softmax has no padding mask input','crates/intel/esp/src/embed/bert/attention.rs','    pub fn forward(&self, hidden: Tensor<3>)', '\n/// Output projection', ['softmax(scores, 3)']),
 ('Mean pooling uses every sequence position','crates/intel/esp/src/embed/bert/model.rs','    pub fn forward_sentence(', '\n#[cfg(test)]', ['mean_dim(1)']),
 ('Batched cosine has independent normalization and ranking','crates/intel/esp/src/embed/index_burn.rs','pub fn cosine_top_k(', '\n/// The GPU all-pairs analog', ['sort_by(', 'add_scalar(1e-12)', '.iter()', 'entries[pos]']),
 ('BERT feed-forward unconditionally uses GELU','crates/intel/esp/src/embed/bert/feed_forward.rs','impl BertIntermediate {','\n/// Contraction projection', ['gelu(self.dense.forward(hidden))']),
]:
 s=(ROOT/path).read_text();first=s.index(start);last=s.index(end,first);excerpt=s[first:last];assert all(n in excerpt for n in required),title
 traces.append({'title':title,'path':path,'source_sha256':sha(ROOT/path),'first_line':s[:first].count('\n')+1,'last_line':s[:last].count('\n')+1,'excerpt':excerpt})
trace_name='embedding_source_traces.json';assert not (HERE/trace_name).exists()
save(trace_name,{'qualification':'Exact source traces only for BERT/Burn. Portable core executes separately; no BERT model, tokenizer artifact, native GPU or full ESP inference build.','traces':traces})
